/* Arcanum: self-contained DW2 Beta v3 Wizard keeper. No network, telemetry or libraries. */
(()=>{'use strict';
const STORAGE='arcanum_dw2_v3_v1';
const SCHOOLS=[
{id:'Abjuration',sub:'Magic itself',verbs:['Temporarily disable','Protect from'],desc:'Wards, suppression and protection'},
{id:'Conjuration',sub:'Objects or outsiders',verbs:['Briefly create','Momentarily summon'],desc:'Temporary objects and summoned outsiders'},
{id:'Divination',sub:'Past, present and future visions',verbs:['Convey','Discern'],desc:'Information, foresight and visions'},
{id:'Enchantment',sub:'Sapient beings',verbs:['Modify emotions','Temporarily charm'],desc:'Charm and influence'},
{id:'Evocation',sub:'Elemental energies',verbs:['Lesser sculpt','Minor channel'],desc:'Fire, ice, lightning, wind and other elements'},
{id:'Illusion',sub:'Sights and/or sounds',verbs:['Cloak','Disguise'],desc:'Sensory deception and concealment'},
{id:'Necromancy',sub:'Unlife',verbs:['Briefly bestow','Radiate'],desc:'Undead and unlife'},
{id:'Transmutation',sub:'Matter',verbs:['Momentarily alter','Repair'],desc:'Physical alterations and restoration'}
];
const PATHS=[
{id:'Illusionist',school:'Illusion',extra:['Make permanent','Substantiate'],tag:'Master deception and perception',starting:'Illusion Magic + Trickster',startingDesc:'Always prepare Illusion in addition to your normal three schools; add Make permanent and Substantiate. Once per scene, clear a Condition when someone believes a lie caused by your illusion.',moves:[
{id:'Alter Perception',desc:'Touch a person or object to alter one perceptible aspect without Cast a Spell; mark a Condition if unwilling. Lasts until dismissed or scene end.'},
{id:'Fool Me Once…',desc:'After someone falls for your illusion, gain advantage and use INT instead of CHA for your next Pull Strings on them. You can share this benefit with involved allies.'},
{id:'Mirror Image',desc:'When you would suffer damage, mark a Condition to prevent it all and reveal your actual position somewhere #near.'},
{id:'The Mirror Stares Back',desc:'Ask a question as if you Sensed Motive the first time an NPC falls for your illusion. Overcharge illusory copies into independent, lasting imitations by marking a Condition.'}]},
{id:'Evoker',school:'Evocation',extra:['Detonate','Magnify'],tag:'Shape devastating elemental magic',starting:'Evocation Magic + Mental Reserves',startingDesc:'Always prepare Evocation in addition to your normal three schools; add Detonate and Magnify. Mark a Condition to instantly prepare a school within your normal limit.',moves:[
{id:'Contingency',desc:'Mark 1–3 Conditions to prepare a spell or Move for a specific trigger, then resolve with a roll modified by Conditions marked.'},
{id:'Elemental Cloak',desc:'Mark 1–3 Conditions for fiery retaliation, icy protection, rock armor, or wild-gale mobility.'},
{id:'Instant Fireball!',desc:'Mark 1–3 Conditions; a #near target and creatures #close to them suffer that many d6 piercing damage.'},
{id:'Power Weapon',desc:'Mark 1–3 Conditions and roll to shape an elemental weapon (1d6, three uses). Trade Blows with it using INT.'}]},
{id:'Necromancer',school:'Necromancy',extra:['Corrupt','Drain'],tag:'Command unlife and forbidden powers',starting:'Necromantic Magic + Rise and Serve',startingDesc:'Always prepare Necromancy in addition to your normal three schools; add Corrupt and Drain. Create a loyal skeleton, zombie or ghoul when your spell kills a living creature.',moves:[
{id:'A Ghost at the Feast',desc:'Create a ghost, shade or shadow instead of a physical undead. Mark a Condition to create both.'},
{id:'Lifeforce Is a Resource',desc:'Gain a special 7–9 spell option: suffer 1 piercing damage. Mark a Condition to redistribute HP between yourself and nearby undead.'},
{id:'Sanctum to Unlife',desc:'Perform a special ritual that imbues a location with unholy power and grants defined benefits.'},
{id:'Shed this Mortal Coil',desc:'Gain a phylactery and the secrets of lichdom.'}]}
];
const CONDITIONS=[{name:'Angry',stat:'INT',desc:'Disadvantage on INT rolls'},{name:'Distracted',stat:'WIS',desc:'Disadvantage on WIS rolls'},{name:'Exhausted',stat:'STR',desc:'Disadvantage on STR rolls'},{name:'Frightened',stat:'DEX',desc:'Disadvantage on DEX rolls'},{name:'Insecure',stat:'CHA',desc:'Disadvantage on CHA rolls'}];
const STARTER_SPELLS=[
{name:'Brief Invisibility',verb:'Cloak',sub:'Sights and/or sounds',category:'Defense',mag:'0',effect:'Hide yourself from view for a few seconds; longer duration raises magnitude.',note:'Concept only; GM approves exact effect.'},
{name:'Windstep',verb:'Minor channel',sub:'Elemental energies',category:'Mobility',mag:'?',effect:'Channel a small gust to assist a jump or make space during a retreat.',note:'Whether it can propel a character needs GM approval.'},
{name:'False Wall',verb:'Disguise',sub:'Sights and/or sounds',category:'Control',mag:'?',effect:'Make a real opening appear blocked to misdirect pursuers.',note:'Visual deception does not create a solid obstacle.'},
{name:'Fire Ward',verb:'Protect from',sub:'Elemental energies',category:'Defense',mag:'?',effect:'Ward yourself against a specified elemental threat such as fire.',note:'Armor, shield or resistance benefits depend on GM ruling.'},
{name:'Temporary Rope',verb:'Briefly create',sub:'Objects or outsiders',category:'Utility',mag:'?',effect:'Create a temporary rope to negotiate a dangerous obstacle.',note:'Size, duration, and strength are GM decisions.'},
{name:'Arcane Suppression',verb:'Temporarily disable',sub:'Magic itself',category:'Control',mag:'?',effect:'Attempt to interrupt an active magical ward or trap briefly.',note:'The ward’s power determines the magnitude.'},
{name:'Spectral Staircase',verb:'Substantiate',sub:'Sights and/or sounds',category:'Mobility',mag:'?',effect:'Attempt to make illusory steps tangible enough to climb.',note:'Ambitious Path concept, requires explicit GM approval.'},
{name:'Arcane Dart',verb:'Minor channel',sub:'Elemental energies',category:'Damage',mag:'0',effect:'A small magical projectile; the rules list a MAG 0 magical dart as 1d4 damage.',note:'GM confirms the specific Evocation implementation.'}
];
const FOCI=[{id:'skull',name:'Bejeweled skull cap',desc:'+1 Armor'},{id:'grimoire',name:'Delicate grimoire',desc:'Once per session, prepare a school instantly'},{id:'staff',name:'Unwieldy staff',desc:'1d6 damage, #close #hand #two-handed'}];
const EQUIPMENT=[{id:'gear',name:'Adventuring gear',max:3,desc:'Mark a use for a useful mundane item'},{id:'books',name:'Bag of books',max:3,desc:'Mark a use to find useful information'},{id:'dagger',name:'Razor dagger',max:0,desc:'1d4 damage, #precise #piercing #thrown'},{id:'potion',name:'Potion of healing',max:1,desc:'Heal half max HP or clear a locked Condition'},{id:'provisions',name:'Provisions',max:3,desc:'Mark once while you Comfort or Support'}];
const NAV=[{id:'sheet',label:'Sheet',icon:'user'},{id:'magic',label:'Magic',icon:'sparkles'},{id:'paths',label:'Paths',icon:'layers'},{id:'play',label:'Play',icon:'dice'},{id:'notes',label:'Notes',icon:'book'}];
const SYMBOLS={
'user':'<path d="M20 21a8 8 0 0 0-16 0"/><circle cx="12" cy="8" r="4"/>',
'sparkles':'<path d="m12 3 1.9 6.1L20 11l-6.1 1.9L12 19l-1.9-6.1L4 11l6.1-1.9z"/><path d="m19 19 1 2 1-2 2-1-2-1-1-2-1 2-2 1z"/>',
'layers':'<path d="m12 2 9 5-9 5-9-5z"/><path d="m3 12 9 5 9-5M3 17l9 5 9-5"/>',
'dice':'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1" fill="currentColor"/><circle cx="16" cy="16" r="1" fill="currentColor"/><circle cx="12" cy="12" r="1" fill="currentColor"/>',
'book':'<path d="M4 19V5a2 2 0 0 1 2-2h13v18H6a2 2 0 0 1-2-2Z"/><path d="M4 17c0-1 1-2 3-2h12"/>',
'download':'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',
'upload':'<path d="M12 17V5m-5 5 5-5 5 5M4 17v4h16v-4"/>',
'moon':'<path d="M20.9 13a9 9 0 0 1-9.9-9.9A9 9 0 1 0 20.9 13Z"/>',
'plus':'<path d="M12 5v14M5 12h14"/>',
'x':'<path d="m18 6-12 12M6 6l12 12"/>',
'check':'<path d="m5 12 4 4L19 6"/>',
'shield':'<path d="m12 22 8-5V6l-8-4-8 4v11l8 5Z"/>',
'heart':'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
'chevron':'<path d="m9 18 6-6-6-6"/>',
'save':'<path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2Z"/><path d="M7 3v7h10V3M7 21v-8h10v8"/>',
'refresh':'<path d="M3 12a9 9 0 0 1 15-6l3 3M21 3v6h-6M21 12a9 9 0 0 1-15 6l-3-3M3 21v-6h6"/>',
'printer':'<path d="M6 9V3h12v6M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><path d="M6 14h12v8H6z"/>',
'copy':'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',
'flame':'<path d="M12 22c5 0 8-3.6 8-8 0-3-1-5-4-8-.5 3-2 4-3 5 0-4-1-6-4-9 0 4-4 7-4 12 0 4.4 3 8 7 8Z"/>',
'arrow':'<path d="M5 12h14m-6-6 6 6-6 6"/>',
'warning':'<path d="m12 2 10 18H2L12 2Z"/><path d="M12 9v4m0 4h.01"/>',
'edit':'<path d="m16 5 3 3M4 20l4-.8L20 7a2.1 2.1 0 0 0-3-3L5 16l-1 4Z"/>',
'check-circle':'<circle cx="12" cy="12" r="10"/><path d="m7 12 3 3 6-6"/>',
'sun':'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4 4l2 2m12 12 2 2M2 12h2m16 0h2M4 20l2-2M18 6l2-2"/>',
'delete':'<path d="M4 7h16m-10 4v6m4-6v6M7 7l1 14h8l1-14M9 7V4h6v3"/>'
};
const ico=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${SYMBOLS[name]||SYMBOLS.sparkles}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const uid=()=>('c'+Date.now().toString(36)+Math.random().toString(36).slice(2,8));
const clamp=(x,min,max)=>Math.max(min,Math.min(max,x));
function fresh(name='Unnamed Wizard') {return {id:uid(),name,pronouns:'',player:'',level:2,stats:{STR:-1,DEX:1,INT:2,WIS:0,CHA:0},hp:7,hpBonus:0,armorBonus:0,xp:0,conditions:{Angry:'clear',Distracted:'clear',Exhausted:'clear',Frightened:'clear',Insecure:'clear'},origins:{ancestry:'',community:'',background:'',look:'',portrait:''},relationships:[],prepared:['Abjuration','Conjuration','Evocation'],forgotten:[],paths:['Illusionist'],moves:[],focus:'skull',equipment:['gear','potion'],used:{gear:0,books:0,potion:0,provisions:0,grimoire:0},wealth:'Modest',treasure:0,spells:STARTER_SPELLS.map(x=>({...x,id:uid(),example:true})),notes:'',sessionNotes:'',advancements:[],createdAt:Date.now(),updatedAt:Date.now()};}
let volatile=false;
let db;
try{const raw=localStorage.getItem(STORAGE);db=raw?JSON.parse(raw):{version:1,activeId:null,characters:[],theme:'dark'};if(!db||!Array.isArray(db.characters))throw Error('Invalid backup');}catch(e){db={version:1,activeId:null,characters:[],theme:'dark'};volatile=true;}
if(!db.characters.length){const c=fresh();db.characters.push(c);db.activeId=c.id;}
if(!db.characters.some(c=>c.id===db.activeId))db.activeId=db.characters[0].id;
let screen='sheet',magicFilter='All',diceMode='cast',diceMag='0',diceExtra='normal',diceLast=null,toastTimer,saveTimer,searchTerm='';
const current=()=>db.characters.find(c=>c.id===db.activeId)||db.characters[0];
const pageTitles={sheet:'Character sheet',magic:'Spellbook',paths:'Paths & growth',play:'Play tools',notes:'Journal & backups'};
const save=()=>{clearTimeout(saveTimer);try{current().updatedAt=Date.now();localStorage.setItem(STORAGE,JSON.stringify(db));volatile=false;updateStatus('Saved locally');}catch(e){volatile=true;updateStatus('Not saved — export backup');toast('Browser storage unavailable or full. Export a JSON backup.');}};
const scheduleSave=()=>{updateStatus('Saving…');clearTimeout(saveTimer);saveTimer=setTimeout(save,360)};
function updateStatus(t){const e=document.getElementById('save-status');if(e)e.textContent=t;}
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}
const maxHp=c=>Math.max(1,6+Math.min(10,Math.max(0,(Number(c.level)||1)-1))+(Number(c.hpBonus)||0));
const armor=c=>(c.focus==='skull'?1:0)+(Number(c.armorBonus)||0);
const hasPath=(c,id)=>c.paths.includes(id);
const bonusSchools=c=>PATHS.filter(p=>hasPath(c,p.id)).map(p=>p.school);
const allPrepared=c=>[...new Set([...c.prepared,...bonusSchools(c)])].filter(id=>!c.forgotten.includes(id));
const availableVerbs=c=>[...new Set(SCHOOLS.filter(s=>allPrepared(c).includes(s.id)).flatMap(s=>[...s.verbs,...(PATHS.find(p=>p.school===s.id&&hasPath(c,p.id))?.extra||[])]))];
const availableSubs=c=>SCHOOLS.filter(s=>allPrepared(c).includes(s.id)).map(s=>s.sub);
const conditionStat=c=>Object.fromEntries(CONDITIONS.map(x=>[x.stat,c.conditions[x.name]!== 'clear']));
const conditionCount=c=>Object.values(c.conditions).filter(v=>v==='marked'||v==='locked').length;
const fmtSign=n=>n>0?'+'+n:String(n);
function renderNav(){document.getElementById('nav-desktop').innerHTML=NAV.map(n=>`<button class="nav-item ${screen===n.id?'active':''}" data-action="nav" data-screen="${n.id}">${ico(n.icon)}<span>${n.label==='Sheet'?'Overview':n.label==='Magic'?'Spellbook':n.label==='Play'?'Play tools':n.label}</span></button>`).join('');document.getElementById('nav-mobile').innerHTML=NAV.map(n=>`<button class="mobile-tab ${screen===n.id?'active':''}" data-action="nav" data-screen="${n.id}" aria-current="${screen===n.id?'page':'false'}">${ico(n.icon)}<span>${n.label}</span></button>`).join('');}
function render(){document.documentElement.dataset.theme=db.theme==='light'?'light':'dark';document.getElementById('page-title').textContent=pageTitles[screen];document.getElementById('page-eyebrow').textContent=esc(current().name).replace(/&amp;/g,'&').slice(0,24).toUpperCase();renderNav();const target=document.getElementById('screen');target.innerHTML={sheet:renderSheet,magic:renderMagic,paths:renderPaths,play:renderPlay,notes:renderNotes}[screen]();}
const pagehead=(title,desc,actions='')=>`<div class="pagehead"><div><div class="eyebrow">DW2 BETA V3 · WIZARD</div><h1>${title}</h1><p>${desc}</p></div>${actions}</div>`;
const field=(label,path,v,placeholder='',type='text')=>`<label class="input-wrap"><span class="field-label">${label}</span><input class="input" data-bind="${path}" type="${type}" placeholder="${esc(placeholder)}" value="${esc(v)}" ${type==='number'?'step="1"':''}/></label>`;
const select=(label,path,val,options)=>`<label class="input-wrap"><span class="field-label">${label}</span><select data-bind="${path}">${options.map(o=>{const value=typeof o==='object'?o.id:o,label=typeof o==='object'?o.name:o;return `<option value="${esc(value)}" ${val===value?'selected':''}>${esc(label)}</option>`}).join('')}</select></label>`;
const pill=(label,type='')=>`<span class="pill ${type}">${esc(label)}</span>`;
const infoCard=(title,body)=>`<section class="card"><div class="card-title"><h2>${title}</h2></div>${body}</section>`;
function renderSheet(){const c=current(),mx=maxHp(c),count=conditionCount(c),stats=CONDITIONS.reduce((a,x)=>(a[x.stat]=x.name,a),{});return pagehead('Your character','Your central character sheet. Changes save automatically on this device.',`<button class="btn hide-mobile" data-action="print">${ico('printer')} Print</button>`)+
`<section class="card hero"><div class="hero-inner"><div class="hero-top"><button class="avatar" data-action="portrait" title="Change character portrait" aria-label="Change character portrait">${c.origins.portrait?`<img src="${esc(c.origins.portrait)}" alt="Character portrait" style="width:100%;height:100%;border-radius:inherit;object-fit:cover"/>`:'✦'}</button><div><h2 class="hero-name">${esc(c.name||'Unnamed Wizard')}</h2><div class="hero-meta">${pill(`Level ${c.level} Wizard`,'accent')}${c.paths.length?c.paths.map(p=>pill(p,'mint')).join(''):pill('No Path acquired')}${pill(`${armor(c)} Armor`)}</div></div></div><div class="hero-controls">${field('Character name','name',c.name,'Your Wizard')}${field('Pronouns','pronouns',c.pronouns,'they/them')}${field('Player name','player',c.player,'Optional')}</div>${c.level<2&&c.paths.length?'<div class="hero-sub">Rules check: Wizard Paths are normally gained through advancements after level 1.</div>':''}</div></section>`+
`<div class="cols-2" style="margin-top:18px"><div class="block-stack">
${infoCard('Attributes',`<div class="stats-grid">${['STR','DEX','INT','WIS','CHA'].map(stat=>`<div class="stat"><div class="stat-name">${stat}</div><div class="stat-value"><button data-action="stat" data-stat="${stat}" data-delta="-1" aria-label="Decrease ${stat}">−</button><span>${fmtSign(c.stats[stat])}</span><button data-action="stat" data-stat="${stat}" data-delta="1" aria-label="Increase ${stat}">+</button></div>${c.conditions[stats[stat]]!=='clear'?'<div class="stat-penalty">Disadvantage</div>':'<div class="micro subtle">&nbsp;</div>'}</div>`).join('')}</div><div class="footnote" style="margin-top:11px">The level-1 starting spread is +2, +1, 0, 0, −1. Adjust values when you gain stat advancements; allocation is not enforced automatically.</div>`)}
${infoCard('Character background',`<div class="field-grid">${field('Ancestry','origins.ancestry',c.origins.ancestry,'Elf, dwarf, human…')}${field('Community','origins.community',c.origins.community,'Arcane academy…')}${field('Background','origins.background',c.origins.background,'Former occupation…')}<label class="input-wrap full"><span class="field-label">Appearance / look</span><textarea data-bind="origins.look" placeholder="Outfit, eyes, markings, focus, demeanor…">${esc(c.origins.look)}</textarea></label></div>`)}
${infoCard('Equipment & focus',`<div class="field-grid">${select('Arcane focus','focus',c.focus,FOCI)}<div><span class="field-label">Focus benefit</span><div class="alert info">${esc(FOCI.find(f=>f.id===c.focus)?.desc||'')}</div></div><div class="full"><span class="field-label">Equipment (choose two at character creation)</span><div class="group-list">${EQUIPMENT.map(e=>`<div class="group-item"><label style="display:flex;gap:10px;align-items:center;flex:1;cursor:pointer"><input type="checkbox" data-equipment="${e.id}" ${c.equipment.includes(e.id)?'checked':''}/><span><strong>${esc(e.name)}</strong><span class="micro muted" style="display:block">${esc(e.desc)}</span></span></label>${e.max&&c.equipment.includes(e.id)?`<div class="flex-row"><button class="btn tiny" data-action="use" data-item="${e.id}" data-delta="1">Use</button><span class="micro muted">${clamp(c.used[e.id]||0,0,e.max)}/${e.max}</span><button class="btn tiny" data-action="use" data-item="${e.id}" data-delta="-1">↺</button></div>`:''}</div>`).join('')}</div></div></div>`)}
</div><div class="block-stack">
${infoCard('Hit points & armor',`<div class="meter-row"><div><div class="field-label">Current HP</div><div class="meter-value">${clamp(c.hp,0,mx)} <span>/ ${mx}</span></div></div><div class="hp-ctrl"><button class="step-btn" data-action="hp" data-delta="-1" aria-label="Lose one HP">−</button><button class="step-btn" data-action="hp" data-delta="1" aria-label="Gain one HP">+</button></div></div><div class="progress"><div class="progress-fill" style="width:${clamp(c.hp/mx*100,0,100)}%"></div></div><div class="flex-spread"><span class="micro muted">Armor: <strong style="color:var(--text)">${armor(c)}</strong></span><span class="micro muted">Max HP: ${mx}</span></div><div class="field-grid" style="margin-top:15px">${field('Extra max HP modifier','hpBonus',c.hpBonus,'0','number')}${field('Extra Armor modifier','armorBonus',c.armorBonus,'0','number')}</div><div class="flex-row" style="margin-top:12px"><button class="btn" data-action="heal-full">${ico('heart')} Full heal</button><button class="btn" data-action="make-camp">${ico('refresh')} Make Camp</button></div>`)}
${infoCard('Conditions',`<p class="para small">Marked or locked Conditions give disadvantage on their corresponding Stat rolls.</p><div class="condition-list">${CONDITIONS.map(k=>`<div class="condition ${c.conditions[k.name]}"><div class="condition-top"><span class="condition-name">${k.name}</span>${pill(k.stat,'')}</div><div class="condition-sub">${k.desc}</div><div class="condition-actions">${['clear','marked','locked'].map(state=>`<button class="choice-btn ${c.conditions[k.name]===state?'selected':''} ${state==='locked'?'lock':''}" data-action="condition" data-condition="${k.name}" data-state="${state}">${state==='clear'?'Clear':state==='marked'?'Mark':'Lock'}</button>`).join('')}</div></div>`).join('')}</div><div style="margin-top:12px" class="flex-spread">${pill(`${count} / 5 active`,count>=4?'danger':'amber')}<button class="btn tiny" data-action="reach-limit" ${count<5?'disabled':''}>Reach Your Limit</button></div>${count>=4?'<div class="alert danger" style="margin-top:12px">You are close to reaching your limit. At five active Conditions, resolve Reach Your Limit.</div>':''}`)}
${infoCard('Experience & level',`<div class="flex-spread"><div><div class="field-label">Level</div><div class="meter-value">${c.level}</div></div><div class="hp-ctrl"><button class="step-btn" data-action="level" data-delta="-1">−</button><button class="step-btn" data-action="level" data-delta="1">+</button></div></div><div class="separator"></div><div class="field-label">XP · Five XP to level up</div><div class="pips">${[1,2,3,4,5].map(i=>`<button class="pip ${c.xp>=i?'filled':''}" data-action="xp" data-value="${i}" aria-label="Set XP to ${i}">${c.xp>=i?'✦':'·'}</button>`).join('')}</div><div class="flex-row" style="margin-top:14px"><button class="btn tiny" data-action="xp-minus">−1 XP</button><button class="btn tiny" data-action="xp-plus">+1 XP</button><div class="spacer"></div>${c.xp>=5?`<button class="btn primary tiny" data-action="level-up">Level up</button>`:''}</div><div class="footnote" style="margin-top:14px">Leveling increases maximum and current HP by 1 (up to +10 from levels), resets XP, and gives one Advancement to choose. Track advancements on Paths.</div>`)}
</div></div>`;
}
function schoolBlock(s,c){const owned=bonusSchools(c).includes(s.id),active=allPrepared(c).includes(s.id),checked=c.prepared.includes(s.id),forgotten=c.forgotten.includes(s.id),availability=owned?'Path bonus':checked?'Prepared':'Not prepared';const ext=PATHS.find(p=>p.school===s.id&&hasPath(c,p.id));return `<div class="group-item"><label class="school-card ${active?'active':''} ${owned?'disabled':''}" style="flex:1"><input hidden type="checkbox" data-school="${s.id}" ${checked||owned?'checked':''} ${owned?'disabled':''}/><div class="school-check">✓</div><div><div class="school-name">${s.id} ${owned?pill('Path bonus','accent'):''}</div><div class="school-desc">Substance: ${esc(s.sub)}</div><div class="school-verbs">Verbs: ${esc([...s.verbs,...(ext?.extra||[])].join(' · '))}</div>${forgotten?'<div class="school-lock">Forgotten until Make Camp</div>':''}</div></label>${forgotten?`<button class="btn tiny" data-action="remember" data-school="${s.id}">Restore</button>`:active?`<button class="btn tiny" data-action="forget" data-school="${s.id}">Forget</button>`:pill(availability)}</div>`}
function renderMagic(){const c=current(),owned=bonusSchools(c),active=allPrepared(c),filtered=c.spells.filter(sp=>{if(magicFilter!=='All'&&magicFilter!==sp.category)return false;const q=searchTerm.toLowerCase();return !q||(sp.name+' '+sp.effect+' '+sp.verb).toLowerCase().includes(q)});return pagehead('Shape the impossible','Create custom spells from prepared-school verbs and substances. Your concepts save to your spellbook.',`<button class="btn primary" data-action="spell-new">${ico('plus')} New spell</button>`)+`<div class="cols-2"><div class="block-stack">${infoCard('Prepared schools',`<div class="flex-spread" style="margin-bottom:13px"><span class="small muted">Choose up to 3 standard schools. Your owned Paths add bonus prepared schools.</span>${pill(`${c.prepared.length}/3 normal`,'accent')}</div><div class="group-list">${SCHOOLS.map(s=>schoolBlock(s,c)).join('')}</div><div class="flex-row" style="margin-top:13px"><button class="btn tiny" data-action="make-camp">${ico('refresh')} Make Camp</button><span class="micro muted">Changing schools normally happens when you Make Camp.</span></div>`)}
${infoCard('Available combinations',`<div class="cols-3" style="grid-template-columns:repeat(3,1fr);gap:9px"><div class="stat" style="padding:13px 4px"><div class="stat-name">Verbs</div><div class="stat-value">${availableVerbs(c).length}</div></div><div class="stat" style="padding:13px 4px"><div class="stat-name">Substances</div><div class="stat-value">${availableSubs(c).length}</div></div><div class="stat" style="padding:13px 4px"><div class="stat-name">Pairings</div><div class="stat-value">${availableVerbs(c).length*availableSubs(c).length}</div></div></div><div class="separator"></div><p class="small muted">All pairings are concepts, not automatically permitted spells. The GM approves feasibility, range, duration, and Magnitude.</p><button class="btn btn-wide" data-action="spell-new">${ico('sparkles')} Open spell builder</button>`)}
</div><div class="block-stack">${infoCard('Spellbook',`<div class="search-row"><input class="input" id="spell-search" type="search" value="${esc(searchTerm)}" placeholder="Search spells…" aria-label="Search spells"/></div><div class="tabset" style="margin-bottom:16px">${['All','Defense','Mobility','Control','Damage','Utility','Other'].map(t=>`<button class="tab ${magicFilter===t?'active':''}" data-action="magic-filter" data-filter="${t}">${t}</button>`).join('')}</div><div class="spell-grid">${filtered.length?filtered.map(sp=>{const ok=availableVerbs(c).includes(sp.verb)&&availableSubs(c).includes(sp.sub);return `<div class="spell-card ${ok?'':'unavailable'}"><div class="spell-head"><div><h3>${esc(sp.name)}</h3><div class="spell-meta" style="margin-top:7px">${pill(sp.category,'accent')}${pill('MAG '+(sp.mag==='?'?'GM':sp.mag))}${ok?pill('Available','mint'):pill('School unavailable','amber')}</div></div><button class="icon-btn" data-action="spell-edit" data-id="${esc(sp.id)}" aria-label="Edit ${esc(sp.name)}">${ico('edit')}</button></div><div class="spell-formula">${esc(sp.verb)} + ${esc(sp.sub)}</div><p>${esc(sp.effect)}</p>${sp.note?`<div class="micro subtle">${esc(sp.note)}</div>`:''}</div>`}).join(''):'<div class="empty" style="grid-column:1/-1">No spells match. Add one with the spell builder.</div>'}</div>`)}
</div></div>`;}
function renderPaths(){const c=current();return pagehead('Path of the arcane','Acquire Paths, unlock verbs, and track individual Path Moves as you level up.')+`<div class="cols-2"><div class="block-stack">${infoCard('Your advancement plan',`<div class="flex-spread"><div><div class="field-label">Current level</div><div class="meter-value">${c.level}</div></div>${pill(`${c.paths.length} Paths owned`,'accent')}</div><div class="separator"></div><p class="small muted">Gaining a Path grants only its Starting Move. Other Path Moves require separate advancements. Your first Path is normally gained by leveling up from level 1.</p><label class="field-label" for="advances">Advancement history / choices</label><textarea id="advances" data-bind="advancementNotes" placeholder="Level 2 — Illusionist Path\nLevel 3 — Mirror Image…">${esc(c.advancementNotes||'')}</textarea>`)}
${infoCard('Spellcasting rules',`<p class="small muted">Prepare 3 schools. An owned Path’s school can be prepared in addition to the normal three. Cast a Spell uses +INT and the GM sets the spell’s Magnitude.</p><div class="group-list"><div class="group-item"><span>MAG below INT</span>${pill('Normal roll','mint')}</div><div class="group-item"><span>MAG equal to INT</span>${pill('Disadvantage','amber')}</div><div class="group-item"><span>MAG above INT</span>${pill('Too powerful','danger')}</div></div><div class="separator"></div><p class="footnote">For a 7–9, your Wizard may mark a Condition, accept a GM twist, or forget a prepared school until Make Camp. Casting requires your focus, both hands otherwise free, and the ability to speak aloud.</p>`)}
</div><div class="block-stack">${PATHS.map(p=>`<section class="path-panel"><div class="path-panel-head"><div><h3>${p.id}</h3><div class="small muted">${esc(p.tag)}</div></div><button class="btn ${hasPath(c,p.id)?'primary':''}" data-action="path" data-path="${p.id}">${hasPath(c,p.id)?ico('check')+' Acquired':'Acquire'}</button></div><div class="separator"></div><div class="pillbar">${pill(p.school,'accent')}${p.extra.map(s=>pill(s)).join('')}</div><p class="small muted" style="margin-top:12px"><strong style="color:var(--text)">${esc(p.starting)}:</strong> ${esc(p.startingDesc)}</p><div style="margin-top:17px"><div class="field-label">Path Moves — gained separately</div>${p.moves.map(m=>`<div class="path-move"><div class="path-move-head"><strong>${esc(m.id)}</strong><button class="btn tiny ${c.moves.includes(m.id)?'primary':''}" data-action="move" data-move="${esc(m.id)}" data-path="${p.id}" ${!hasPath(c,p.id)?'disabled':''}>${c.moves.includes(m.id)?'Learned':'Learn'}</button></div><p>${esc(m.desc)}</p></div>`).join('')}</div></section>`).join('')}</div></div>`;}
function renderPlay(){const c=current();const modes=[{id:'cast',label:'Cast a Spell',stat:'INT',hint:'Wizard spellcasting: GM assigns Magnitude. Equal to INT means disadvantage.'},{id:'melee',label:'Trade Blows · melee',stat:'STR',hint:'Weapon exchange in melee, usually dealing and suffering damage.'},{id:'ranged',label:'Trade Blows · ranged',stat:'DEX',hint:'Physical ranged attacks, not normally Wizard spell projectiles.'},{id:'dodge',label:'Defy Danger · dodge',stat:'DEX',hint:'Dodging, escaping, or outpacing a danger.'},{id:'outsmart',label:'Defy Danger · outsmart',stat:'INT',hint:'Analyzing or outsmarting a danger.'},{id:'sneak',label:'Sneak Past',stat:'DEX',hint:'Stealthily evade notice.'},{id:'wis',label:'Defy Danger · resist',stat:'WIS',hint:'Resist or scrutinize a danger.'},{id:'cha',label:'Defy Danger · trick',stat:'CHA',hint:'Charm, trick, impress, or provoke a danger.'}];const mode=modes.find(m=>m.id===diceMode)||modes[0],penalty=CONDITIONS.find(x=>x.stat===mode.stat&&c.conditions[x.name]!=='clear');let mag=Number(diceMag),tooHigh=mode.id==='cast'&&diceMag!=='?'&&mag>c.stats.INT;return pagehead('At the table','Fast tools for combat, checks, session upkeep, and Conditions.')+`<div class="cols-2"><div class="block-stack">${infoCard('Dice roller',`${select('Move','__diceMode',diceMode,modes.map(m=>({id:m.id,name:m.label})))}<div class="small muted" style="margin:8px 0 14px">${esc(mode.label)} · ${esc(mode.hint)}</div><div class="field-grid">${mode.id==='cast'?`<label><span class="field-label">Spell magnitude</span><select id="dice-mag">${['0','1','2','3','4','?'].map(v=>`<option ${v===diceMag?'selected':''} value="${v}">${v==='?'?'GM to decide':v}</option>`).join('')}</select></label>`:''}<label><span class="field-label">Roll modifier</span><select id="dice-extra">${['normal','advantage','disadvantage'].map(v=>`<option value="${v}" ${diceExtra===v?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></label></div><div class="dice-area" style="margin-top:16px">${diceLast?`<div class="rolling-number">${diceLast.dice.map((d,i)=>`<div class="roll-die" style="${diceLast.omitted===i?'opacity:.35;text-decoration:line-through':''}">${d}</div>`).join('')}<span class="muted">${fmtSign(diceLast.mod)}</span></div><div class="dice-result">${diceLast.total}</div><div class="dice-summary">${esc(diceLast.outcome)} · ${esc(diceLast.mode)}</div>`:`<div style="font-size:36px;color:var(--accent)">✦</div><div class="dice-result">—</div><div class="dice-minor">2d6 + ${mode.stat} (${fmtSign(c.stats[mode.stat])})</div>`}<button class="btn primary btn-wide" style="margin-top:15px" data-action="roll" ${tooHigh?'disabled':''}>${ico('dice')} ${tooHigh?'MAG beyond INT — ritual needed':'Roll dice'}</button></div>${penalty?`<div class="alert" style="margin-top:12px">${penalty.name} imposes disadvantage on ${mode.stat} rolls.</div>`:''}${mode.id==='cast'&&Number(diceMag)===c.stats.INT?'<div class="alert" style="margin-top:12px">MAG equals casting stat: roll with disadvantage.</div>':''}<div class="footnote" style="margin-top:15px">On 10+ you generally succeed; 7–9 succeeds with complications; 6− creates trouble and normally awards 1 XP. Move-specific rules control the exact result. Dice rolls are not permanently saved.</div>`)}
${infoCard('Move reference',`<div class="group-list"><div class="group-item" style="display:block"><strong>Cast a Spell +INT</strong><div class="small muted">10+: effect works · 7–9: effect works with Condition, GM twist or forget a school · 6−: trouble +1 XP.</div></div><div class="group-item" style="display:block"><strong>Trade Blows +STR/+DEX</strong><div class="small muted">Typically exchange damage. On 10+ gain a benefit; on 7–9 accept complication; on 6− choose minimum dealt or maximum suffered.</div></div><div class="group-item" style="display:block"><strong>Defy Danger +appropriate stat</strong><div class="small muted">10+: overcome obstacle · 7–9: succeed with drawback · 6−: things go wrong.</div></div><div class="group-item" style="display:block"><strong>Mirror Image · Illusionist Move</strong><div class="small muted">If learned, mark a Condition when taking damage to prevent all of it and reveal a #near position.</div></div></div>`)}
</div><div class="block-stack">${infoCard('Quick combat tracker',`<div class="meter-row"><div><div class="field-label">Current HP</div><div class="meter-value">${c.hp}<span> / ${maxHp(c)}</span></div></div><div class="hp-ctrl"><button class="step-btn" data-action="hp" data-delta="-1">−</button><button class="step-btn" data-action="hp" data-delta="1">+</button><button class="btn" data-action="heal-full">Full heal</button></div></div><div class="separator"></div><div class="field-label">Conditions</div>${CONDITIONS.map(x=>`<div class="group-item" style="margin-top:7px"><div><strong>${x.name}</strong><div class="micro muted">${x.stat} disadvantage</div></div><div class="flex-row">${pill(c.conditions[x.name],c.conditions[x.name]==='locked'?'danger':c.conditions[x.name]==='marked'?'amber':'mint')}<button class="btn tiny" data-action="cycle-condition" data-condition="${x.name}">Change</button></div></div>`).join('')}<button class="btn btn-wide" style="margin-top:15px" data-action="make-camp">${ico('refresh')} Make Camp</button>`)}
${infoCard('Spellcasting checklist',`<div class="group-list"><div class="group-item">${ico('check-circle')} Arcane focus available</div><div class="group-item">${ico('check-circle')} Both hands otherwise free</div><div class="group-item">${ico('check-circle')} Able to speak aloud</div><div class="group-item">${ico('check-circle')} Verb + substance from currently available schools</div></div><p class="footnote" style="margin-top:14px">For your mobility/illusion build, remember that ranged spell attacks use Cast a Spell +INT, while a physical bow uses Trade Blows +DEX.</p>`)}
</div></div>`;}
function renderNotes(){const c=current();return pagehead('Journal & safekeeping','Keep campaign notes, relationships, and backups of every character you create.')+`<div class="cols-2"><div class="block-stack">${infoCard('Campaign journal',`<label><span class="field-label">Notes · auto-saved locally</span><textarea class="notes-textarea" data-bind="notes" placeholder="NPCs, clues, spell experiments, GM rulings, quest leads…">${esc(c.notes)}</textarea></label>`)}
${infoCard('Relationships',`<p class="para small">Record PCs, relationship descriptions, and Depth (0–3).</p><div class="group-list">${c.relationships.length?c.relationships.map((rel,i)=>`<div class="group-item"><div style="flex:1"><strong>${esc(rel.name)}</strong><div class="micro muted">${esc(rel.description)}</div><div class="micro muted">Depth: ${clamp(rel.depth||0,0,3)}</div></div><button class="icon-btn" data-action="relationship-edit" data-index="${i}" aria-label="Edit relationship">${ico('edit')}</button></div>`).join(''):'<div class="empty">No relationships yet</div>'}</div><button class="btn" style="margin-top:13px" data-action="relationship-new">${ico('plus')} Add relationship</button>`)}
</div><div class="block-stack">${infoCard('Your characters',`<div class="group-list">${db.characters.map(x=>`<div class="character-row ${x.id===c.id?'current':''}"><div class="flex-row" style="min-width:0"><div class="char-mini">✦</div><div><strong>${esc(x.name||'Unnamed Wizard')}</strong><p>Level ${x.level} · ${x.paths.join(' + ')||'Wizard'}</p></div></div>${x.id===c.id?pill('Current','accent'):`<button class="btn tiny" data-action="character-switch" data-id="${x.id}">Open</button>`}</div>`).join('')}</div><div class="flex-row" style="margin-top:14px"><button class="btn" data-action="character-new">${ico('plus')} New</button><button class="btn" data-action="character-duplicate">${ico('copy')} Duplicate</button></div><div class="separator"></div><button class="btn danger" data-action="character-delete">${ico('delete')} Delete current character</button>`)}
${infoCard('Export & restore',`<div class="alert info" style="margin-bottom:17px">Your edits are saved automatically <strong>in this browser on this device</strong>. They do not sync across devices. Export a backup to keep your character safe or move it to your phone.</div><div class="group-list"><button class="btn btn-wide primary" data-action="export">${ico('download')} Export ALL characters · JSON</button><button class="btn btn-wide" data-action="import">${ico('upload')} Import a JSON backup</button><button class="btn btn-wide" data-action="export-character">${ico('download')} Export current character only</button><button class="btn btn-wide" data-action="print">${ico('printer')} Print character sheet</button></div><p class="footnote" style="margin-top:14px">Import adds characters from a saved backup without overwriting existing ones. Backups include stats, notes, spells, and portrait data. Keep a copy somewhere you control (e.g., Files, Google Drive, or another cloud folder).</p>`)}
${infoCard('App information',`<div class="group-list"><div class="group-item"><span>Theme</span><button class="btn tiny" data-action="theme">${db.theme==='dark'?'Dark':'Light'} · change</button></div><div class="group-item"><span>Rule source</span>${pill('Dungeon World 2 Beta v3')}</div><div class="group-item"><span>Storage</span>${pill(volatile?'Needs backup':'Local browser','accent')}</div></div><p class="footnote" style="margin-top:13px">Built from your DW2 Beta v3 Character Keeper export. This is an unofficial character tool. Spell examples are proposals requiring GM approval. For offline phone installation, use the hosted PWA version over HTTPS; a downloaded local HTML file may have different browser storage behavior.</p>`)}
</div></div>`;}
function modal(title,content){document.getElementById('modal-title').textContent=title;document.getElementById('modal-content').innerHTML=content;document.getElementById('modal-scrim').classList.remove('hidden');document.body.style.overflow='hidden';}
function closeModal(){document.getElementById('modal-scrim').classList.add('hidden');document.body.style.overflow='';}
function opts(arr,value){return arr.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('')}
function spellModal(id){const c=current(),sp=c.spells.find(x=>x.id===id)||{id:'',name:'',verb:availableVerbs(c)[0]||'Cloak',sub:availableSubs(c)[0]||'Sights and/or sounds',category:'Utility',mag:'?',effect:'',note:''};const verbs=[...new Set([...SCHOOLS.flatMap(s=>s.verbs),...PATHS.flatMap(p=>p.extra)])];const subs=SCHOOLS.map(s=>s.sub);modal(id?'Edit spell':'Create a spell',`<form id="spell-form" data-id="${esc(sp.id)}"><div class="field-grid"><label class="full"><span class="field-label">Spell name</span><input name="name" class="input" required maxlength="100" value="${esc(sp.name)}" placeholder="e.g. Windstep"/></label><label><span class="field-label">Verb</span><select name="verb">${opts(verbs,sp.verb)}</select></label><label><span class="field-label">Substance</span><select name="sub">${opts(subs,sp.sub)}</select></label><label><span class="field-label">Category</span><select name="category">${opts(['Defense','Mobility','Control','Damage','Utility','Other'],sp.category)}</select></label><label><span class="field-label">Magnitude (GM-approved)</span><select name="mag">${opts(['?','0','1','2','3','4','5+'],sp.mag)}</select></label><label class="full"><span class="field-label">Desired effect</span><textarea name="effect" required placeholder="Describe what you want this spell to do...">${esc(sp.effect)}</textarea></label><label class="full"><span class="field-label">GM ruling / limits</span><textarea name="note" placeholder="Range, duration, narrative limits, approvals...">${esc(sp.note)}</textarea></label></div><div class="modal-actions">${id?`<button type="button" class="btn danger" data-action="spell-delete" data-id="${esc(id)}">${ico('delete')} Delete</button>`:''}<button type="button" class="btn" data-action="close-modal">Cancel</button><button type="submit" class="btn primary">${ico('save')} Save spell</button></div></form><p class="footnote">You can draft a future spell even if its school is not currently prepared. Unavailable spells are labeled in the spellbook.</p>`);}
function relationshipModal(index){const r=index===null?{name:'',description:'',depth:0}:current().relationships[index];modal(index===null?'Add relationship':'Edit relationship',`<form id="relationship-form" data-index="${index===null?'':index}"><div class="field-grid"><label class="full"><span class="field-label">Character name</span><input class="input" name="name" required value="${esc(r.name)}"/></label><label class="full"><span class="field-label">Relationship</span><textarea name="description">${esc(r.description)}</textarea></label><label><span class="field-label">Depth</span><select name="depth">${opts(['0','1','2','3'],String(r.depth))}</select></label></div><div class="modal-actions">${index!==null?`<button type="button" class="btn danger" data-action="relationship-delete" data-index="${index}">Delete</button>`:''}<button type="button" class="btn" data-action="close-modal">Cancel</button><button type="submit" class="btn primary">Save relationship</button></div></form>`);}
function campModal(){const c=current(),marked=CONDITIONS.filter(x=>c.conditions[x.name]==='marked');modal('Make Camp',`<p class="para">Once per session, recover all HP and clear <strong>one marked Condition</strong>. Forgotten prepared schools are restored. Your normal three prepared schools can be changed on the Magic page.</p><label><span class="field-label">Condition to clear</span><select id="camp-condition">${opts(['None',...marked.map(x=>x.name)],marked.length?marked[0].name:'None')}</select></label><div class="alert info" style="margin-top:14px">The world advances while you rest. Your GM may make threats progress.</div><div class="modal-actions"><button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="camp-confirm">Finish Make Camp</button></div>`);}
function limitModal(){const c=current();modal('Reach Your Limit',`<p class="para">When all five Conditions are marked or locked, clear marked Conditions, then choose and roleplay an outburst. Lock the associated Condition.</p><label><span class="field-label">Condition to lock after the outburst</span><select id="limit-condition">${opts(CONDITIONS.map(x=>x.name),'Angry')}</select></label><div class="modal-actions"><button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="limit-confirm">Resolve limit</button></div>`);}
function portraitModal(){modal('Character portrait',`<p class="para">Add a personal portrait. It will be stored in your character backup and resized for mobile use.</p><input id="portrait-input" type="file" accept="image/png,image/jpeg,image/webp" class="input"/><div class="modal-actions"><button class="btn danger" data-action="portrait-remove">Remove portrait</button><button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="portrait-save">Save portrait</button></div>`);}
function characterNewModal(){modal('New Wizard',`<form id="new-character-form"><label><span class="field-label">Character name</span><input class="input" name="name" autofocus required placeholder="Your wizard's name" maxlength="100"/></label><label style="display:block;margin-top:13px"><span class="field-label">Starting preset</span><select name="preset"><option value="level1">Level 1 · starting Wizard (3 schools, no Path)</option><option value="illusionist">Level 2 · Illusionist build (4 schools)</option></select></label><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Create Wizard</button></div></form>`);}
function pathToggle(id){const c=current(),p=PATHS.find(x=>x.id===id);if(!p)return;if(hasPath(c,id)){if(!confirm(`Remove ${id} Path? Its unlocked moves will also be removed.`))return;c.paths=c.paths.filter(v=>v!==id);c.moves=c.moves.filter(m=>!p.moves.some(x=>x.id===m));c.prepared=[...new Set(c.prepared)].slice(0,3);}else{if(c.paths.length>=2){toast('This Wizard sheet tracks up to two Wizard Paths.');return}c.paths.push(id);if(c.prepared.includes(p.school))c.prepared=c.prepared.filter(x=>x!==p.school);if(c.level===1)toast('Rules note: Paths normally require a level-up advancement.');}save();render();}
function exportJSON(data,filename){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('JSON backup created. Keep a copy outside this browser.');}
function exportAll(){save();exportJSON({format:'Arcanum DW2 Wizard Keeper',version:1,exportedAt:new Date().toISOString(),characters:db.characters},'Arcanum-DW2-all-characters.json')}
function exportChar(){save();exportJSON({format:'Arcanum DW2 Wizard Keeper',version:1,exportedAt:new Date().toISOString(),characters:[current()]},`Arcanum-${(current().name||'wizard').replace(/[^a-z0-9-]+/gi,'-')}.json`)}
function normalizeImported(x){if(!x||typeof x!=='object'||Array.isArray(x))return null;const d=fresh(String(x.name||'Imported wizard').slice(0,120));const safe=(key,defaultVal)=>Array.isArray(x[key])?x[key]:defaultVal;
Object.assign(d,{...x,id:uid(),name:String(x.name||'Imported wizard').slice(0,120),level:clamp(Number(x.level)||1,1,99),stats:{...d.stats,...(x.stats||{})},origins:{...d.origins,...(x.origins||{})},conditions:{...d.conditions,...(x.conditions||{})},hp:Math.max(0,Number(x.hp)||0),paths:safe('paths',[]).filter(p=>PATHS.some(q=>q.id===p)),moves:safe('moves',[]).filter(m=>PATHS.some(q=>q.moves.some(v=>v.id===m))),prepared:safe('prepared',[]).filter(p=>SCHOOLS.some(q=>q.id===p)).slice(0,3),forgotten:safe('forgotten',[]),equipment:safe('equipment',[]).filter(e=>EQUIPMENT.some(q=>q.id===e)),used:{...d.used,...(x.used||{})},spells:safe('spells',[]).slice(0,300).filter(sp=>sp&&typeof sp==='object').map(sp=>({...sp,id:uid()})),relationships:safe('relationships',[]).slice(0,40).filter(r=>r&&typeof r==='object'),createdAt:Date.now(),updatedAt:Date.now()});return d;}
function handleImport(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(reader.result);if(data.format!=='Arcanum DW2 Wizard Keeper'||!Array.isArray(data.characters))throw Error('Invalid Arcanum backup');if(data.characters.length>100)throw Error('Too many characters in one backup');const imported=data.characters.map(normalizeImported).filter(Boolean);if(!imported.length)throw Error('No usable characters');db.characters.push(...imported);db.activeId=imported[0].id;screen='sheet';save();render();toast(`Imported ${imported.length} character${imported.length!==1?'s':''}. Existing characters were preserved.`)}catch(e){toast('Could not import backup: '+e.message)}};reader.readAsText(file);}
function roll(){const c=current();const modeMap={cast:'INT',melee:'STR',ranged:'DEX',dodge:'DEX',outsmart:'INT',sneak:'DEX',wis:'WIS',cha:'CHA'};let st=modeMap[diceMode]||'INT';if(diceMode==='cast'&&diceMag!=='?'&&Number(diceMag)>c.stats.INT){toast('Spell Magnitude is above your INT. Try a lesser effect or Ritual.');return;}let sources=(diceExtra==='advantage'?1:diceExtra==='disadvantage'?-1:0);if(diceMode==='cast'&&diceMag!=='?'&&Number(diceMag)===c.stats.INT)sources--;if(CONDITIONS.some(x=>x.stat===st&&c.conditions[x.name]!=='clear'))sources--;const d=sources>0?'advantage':sources<0?'disadvantage':'normal';let dice=Array.from({length:d==='normal'?2:3},()=>Math.floor(Math.random()*6)+1);let use=dice.slice();let omitted=null;if(d!=='normal'){const keep=d==='advantage'?[...dice].sort((a,b)=>b-a).slice(0,2):[...dice].sort((a,b)=>a-b).slice(0,2);const removed=d==='advantage'?Math.min(...dice):Math.max(...dice);omitted=dice.findIndex(z=>z===removed);use=keep;}
const total=use.reduce((a,b)=>a+b,0)+c.stats[st];diceLast={dice,omitted,mod:c.stats[st],total,outcome:total>=10?'10+ · Success':total>=7?'7–9 · Success with complication':'6− · Trouble',mode:st+(d!=='normal'?' · '+d:'')};render();}
function changeBind(path,val){if(path==='__diceMode'){diceMode=val;diceLast=null;render();return;}const c=current(),segments=path.split('.');let cur=c;for(let i=0;i<segments.length-1;i++)cur=cur[segments[i]]||(cur[segments[i]]={});const last=segments.at(-1);if(['hpBonus','armorBonus','level','treasure'].includes(path))val=Number(val)||0;cur[last]=val;scheduleSave();if(path==='name'){document.getElementById('page-eyebrow').textContent=String(val).slice(0,24).toUpperCase();}}
function refreshAfterChange(path){if(['level','hpBonus','armorBonus','focus','wealth','name','origins.portrait'].includes(path))render();}
function handleAction(a){const c=current(),kind=a.dataset.action;switch(kind){
case 'nav':screen=a.dataset.screen;searchTerm='';render();window.scrollTo({top:0,behavior:'smooth'});break;
case 'theme':db.theme=db.theme==='dark'?'light':'dark';save();render();break;
case 'export':exportAll();break;
case 'export-character':exportChar();break;
case 'import':document.getElementById('import-file').click();break;
case 'print':screen='sheet';render();requestAnimationFrame(()=>window.print());break;
case 'portrait':portraitModal();break;
case 'portrait-remove':c.origins.portrait='';save();closeModal();render();break;
case 'portrait-save':{const f=document.getElementById('portrait-input').files?.[0];if(!f){toast('Choose an image first.');break}if(f.size>8*1024*1024){toast('Portrait must be smaller than 8 MB.');break}const rd=new FileReader();rd.onload=()=>{const img=new Image();img.onload=()=>{const canvas=document.createElement('canvas'),scale=Math.min(1,360/Math.max(img.width,img.height));canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);c.origins.portrait=canvas.toDataURL('image/jpeg',.78);save();closeModal();render();toast('Portrait saved.');};img.onerror=()=>toast('Could not read this image.');img.src=rd.result;};rd.readAsDataURL(f);break}
case 'close-modal':closeModal();break;
case 'stat':{const stat=a.dataset.stat;const limit=c.level>=10?3:2;c.stats[stat]=clamp(Number(c.stats[stat])+Number(a.dataset.delta),-3,limit);save();render();break}
case 'hp':c.hp=clamp(Number(c.hp)+Number(a.dataset.delta),0,maxHp(c));save();render();break;
case 'heal-full':c.hp=maxHp(c);save();render();break;
case 'xp':c.xp=c.xp===Number(a.dataset.value)?Number(a.dataset.value)-1:Number(a.dataset.value);save();render();break;
case 'xp-minus':c.xp=clamp(c.xp-1,0,5);save();render();break;
case 'xp-plus':c.xp=clamp(c.xp+1,0,5);save();render();break;
case 'level':{const old=maxHp(c);c.level=clamp(c.level+Number(a.dataset.delta),1,99);c.hp=clamp(c.hp+(maxHp(c)-old),0,maxHp(c));save();render();break}
case 'level-up':if(c.xp<5)return;{const old=maxHp(c);c.level++;c.xp=0;c.hp=clamp(c.hp+(maxHp(c)-old),0,maxHp(c));screen='paths';save();render();toast('Level gained. Record your advancement on the Paths page.');break}
case 'condition':c.conditions[a.dataset.condition]=a.dataset.state;save();render();break;
case 'cycle-condition':{let prev=c.conditions[a.dataset.condition];c.conditions[a.dataset.condition]=prev==='clear'?'marked':prev==='marked'?'locked':'clear';save();render();break}
case 'reach-limit':limitModal();break;
case 'limit-confirm':{const locked=document.getElementById('limit-condition').value;for(const key of Object.keys(c.conditions)){if(c.conditions[key]==='marked')c.conditions[key]='clear';}c.conditions[locked]='locked';save();closeModal();render();toast('Reach Your Limit resolved. Roleplay the outburst.');break}
case 'make-camp':campModal();break;
case 'camp-confirm':{const k=document.getElementById('camp-condition').value;c.hp=maxHp(c);if(k!=='None'&&c.conditions[k]==='marked')c.conditions[k]='clear';c.forgotten=[];save();closeModal();render();toast('Made Camp: HP recovered and one marked Condition cleared.');break}
case 'use':{const e=EQUIPMENT.find(e=>e.id===a.dataset.item);c.used[e.id]=clamp((c.used[e.id]||0)+Number(a.dataset.delta),0,e.max);save();render();break}
case 'remember':c.forgotten=c.forgotten.filter(x=>x!==a.dataset.school);save();render();break;
case 'forget':if(!c.forgotten.includes(a.dataset.school))c.forgotten.push(a.dataset.school);save();render();break;
case 'magic-filter':magicFilter=a.dataset.filter;render();break;
case 'spell-new':spellModal(null);break;
case 'spell-edit':spellModal(a.dataset.id);break;
case 'spell-delete':if(confirm('Delete this spell from your spellbook?')){c.spells=c.spells.filter(s=>s.id!==a.dataset.id);save();closeModal();render();}break;
case 'path':pathToggle(a.dataset.path);break;
case 'move':{const p=PATHS.find(p=>p.id===a.dataset.path);if(!p||!hasPath(c,p.id))return;const id=a.dataset.move;if(c.moves.includes(id))c.moves=c.moves.filter(x=>x!==id);else c.moves.push(id);save();render();break;}
case 'roll':roll();break;
case 'relationship-new':relationshipModal(null);break;
case 'relationship-edit':relationshipModal(Number(a.dataset.index));break;
case 'relationship-delete':if(confirm('Delete this relationship?')){c.relationships.splice(Number(a.dataset.index),1);save();closeModal();render();}break;
case 'character-new':characterNewModal();break;
case 'character-duplicate':{const x=normalizeImported(current());x.name+=' (copy)';db.characters.push(x);db.activeId=x.id;save();render();toast('Duplicate character created.');break;}
case 'character-switch':db.activeId=a.dataset.id;save();render();toast('Character opened.');break;
case 'character-delete':if(db.characters.length<=1){toast('Create another character before deleting the last one.');break;}if(confirm(`Delete ${c.name} from this browser? This cannot be undone unless you have a backup.`)){db.characters=db.characters.filter(x=>x.id!==c.id);db.activeId=db.characters[0].id;save();render();}break;
default:break;
}}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a){e.preventDefault();handleAction(a)}});
document.addEventListener('change',e=>{const a=e.target;if(a.matches('[data-bind]')){changeBind(a.dataset.bind,a.value);refreshAfterChange(a.dataset.bind)}if(a.matches('[data-school]')){const c=current(),s=a.dataset.school;if(a.checked){if(c.prepared.length>=3){toast('Maximum three normal Prepared Schools. Owned Paths grant their schools separately.');render();return}c.prepared.push(s);}else c.prepared=c.prepared.filter(x=>x!==s);save();render();}if(a.matches('[data-equipment]')){const c=current(),id=a.dataset.equipment;if(a.checked){if(c.equipment.length>=2){toast('At character creation, choose two extra equipment items.');render();return}c.equipment.push(id);}else{c.equipment=c.equipment.filter(x=>x!==id);}save();render();}if(a.id==='dice-mag'){diceMag=a.value;diceLast=null;render();}if(a.id==='dice-extra'){diceExtra=a.value;diceLast=null;render();}});
document.addEventListener('input',e=>{if(e.target.matches('[data-bind]')&&!e.target.matches('select'))changeBind(e.target.dataset.bind,e.target.value);if(e.target.id==='spell-search'){searchTerm=e.target.value;const pos=e.target.selectionStart;render();const field=document.getElementById('spell-search');if(field){field.focus();field.setSelectionRange(pos,pos);}}});
document.addEventListener('submit',e=>{if(e.target.id==='spell-form'){e.preventDefault();const f=e.target,form=new FormData(f),c=current(),id=f.dataset.id;const sp={id:id||uid(),name:String(form.get('name')).trim().slice(0,110),verb:String(form.get('verb')),sub:String(form.get('sub')),category:String(form.get('category')),mag:String(form.get('mag')),effect:String(form.get('effect')).trim().slice(0,2000),note:String(form.get('note')).trim().slice(0,2000),example:false};if(!sp.name||!sp.effect){toast('Enter a spell name and desired effect.');return;}const i=c.spells.findIndex(x=>x.id===id);if(i>=0)c.spells[i]=sp;else c.spells.unshift(sp);save();closeModal();render();toast('Spell saved.');}else if(e.target.id==='relationship-form'){e.preventDefault();const f=e.target,d=new FormData(f),r={name:String(d.get('name')).slice(0,100),description:String(d.get('description')).slice(0,800),depth:Number(d.get('depth'))};let i=f.dataset.index===''?-1:Number(f.dataset.index);if(i<0)current().relationships.push(r);else current().relationships[i]=r;save();closeModal();render();}else if(e.target.id==='new-character-form'){e.preventDefault();const f=new FormData(e.target),c=fresh(String(f.get('name')||'New Wizard').trim().slice(0,100));if(f.get('preset')==='level1'){c.level=1;c.hp=6;c.paths=[];c.prepared=['Abjuration','Evocation','Illusion'];c.spells=STARTER_SPELLS.map(sp=>({...sp,id:uid()}));}db.characters.push(c);db.activeId=c.id;screen='sheet';save();closeModal();render();toast('New character created.');}});
document.getElementById('import-file').addEventListener('change',e=>{handleImport(e.target.files?.[0]);e.target.value='';});
document.getElementById('modal-scrim').addEventListener('click',e=>{if(e.target.id==='modal-scrim')closeModal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
// Initial data and offline registration
render();if(!volatile)save();else updateStatus('Storage unavailable — export backup');document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=ico(el.dataset.icon));if('serviceWorker'in navigator&&/^https?:$/.test(location.protocol)){navigator.serviceWorker.register('./sw.js').catch(()=>{});} 
})();
